<template><q-page class="q-pa-lg"><div class="text-overline text-primary">COMPANY UPDATES</div><div class="page-title">Announcements</div><p class="muted">Stay up to date with the latest company news.</p><div v-if="loading" class="text-center q-pa-xl"><q-spinner color="primary" size="40px"/></div><div v-else-if="!rows.length" class="text-center q-pa-xl"><q-icon name="campaign" size="48px" color="indigo-3"/><div class="text-h6 q-mt-sm">No announcements yet</div><div class="muted">New announcements will appear here.</div></div><div v-else class="row q-col-gutter-lg q-mt-md"><div v-for="a in rows" :key="a.id" class="col-12 col-md-6 col-lg-4"><q-card flat bordered class="announcement-card" :class="a.priority==='urgent'?'urgent-card':a.priority==='important'?'important-card':''"><q-card-section class="row items-start no-wrap"><div class="col"><div class="text-subtitle1 text-weight-bold">{{a.title}}</div><div class="muted q-mt-xs" style="white-space:pre-wrap">{{a.message}}</div></div><q-badge :color="priorityColor(a.priority)" :label="cap(a.priority)" class="q-ml-sm"/></q-card-section><q-separator/><q-card-section class="row items-center text-caption muted"><q-icon name="person" size="16px" class="q-mr-xs"/>{{a.creator_name}}<q-space/><q-icon name="schedule" size="16px" class="q-mr-xs"/>{{a.created_at}}</q-card-section></q-card></div></div></q-page></template>
<script setup>import {ref,onMounted} from 'vue';import api from '../services/api';const rows=ref([]),loading=ref(false);const cap=x=>x?x[0].toUpperCase()+x.slice(1):'';const priorityColor=x=>x==='urgent'?'negative':x==='important'?'orange':'positive';async function load(){loading.value=true;try{rows.value=(await api.get('/announcements/mine')).data.data}finally{loading.value=false}}onMounted(load)</script>